import React, { useState } from 'react';
import './Hero.css';

export function Hero() {
  const [copied, setCopied] = useState(false);

  return (
    <section className="h-hero" id="hero">
      <div className="h-hero__inner">
        <div className="h-hero__content">
          <div className="h-hero__badge">ZERO COLD STARTS — 100% DETERMINISTIC</div>
          <h1 className="h-hero__title">DEPLOY RAW COMPUTE TO THE BORDERLESS EDGE</h1>
          <p className="h-hero__subtitle">
            Autonomous AI runtime and edge computing for modern teams. Zero latency, deterministic execution, and 100% uptime.
          </p>
          <div className="h-hero__actions">
            <a href="mailto:support@hyperforge.com" className="h-hero__btn-primary">START CLUSTERING</a>
            <button
              type="button"
              className="h-hero__btn-secondary"
              onClick={() => {
                setCopied(true);
                setTimeout(() => setCopied(false), 2000);
              }}
            >
              {copied ? 'COPIED' : 'COPY TO CLIPBOARD'}
            </button>
          </div>
        </div>

        <div className="h-hero__code-snippet">
          <pre className="h-code-snippet__shell">
            <code>
              <span className="h-code-snippet__prompt">$</span>
              <span className="h-code-snippet__command">npm install hyperforge</span>
            </code>
          </pre>
          <div className="h-code-snippet__copy-indicator" aria-hidden="true">
            {copied ? '✔' : '📋'}
          </div>
        </div>
      </div>
    </section>
  );
}

